const nconf = require('nconf');

const user = require('../user');
const privileges = require('../privileges');

const wellKnown = module.exports;

/*
 * GET /.well-known/webfinger
 *
 * Implements a basic WebFinger (RFC 7033) endpoint for federated identity
 * discovery. The `resource` query parameter must be an `acct:` URI pointing
 * at this NodeBB's hostname, e.g. `acct:username@nodebb.example.com`.
 *
 * Response (200):
 * {
 *   subject: <the original resource string>,
 *   aliases: [<uid-based profile URL>, <slug-based profile URL>],
 *   links: [ { rel: 'http://webfinger.net/rel/profile-page', type: 'text/html', href: <profile URL> } ]
 * }
 */
wellKnown.webfinger = async function (req, res) {
	const resource = req.query.resource;
	const hostname = (nconf.get('url_parsed') || {}).hostname;

	// Validate the resource parameter
	if (!resource || !String(resource).startsWith('acct:') || !String(resource).endsWith(`@${hostname}`)) {
		return res.status(400).json({
			error: '[[error:invalid-data]]',
		});
	}

	// Authorization: evaluate against the requesting user, or the Guest
	// role (uid 0) for anonymous requests. Access is gated by the
	// `groups:view:users` global permission.
	const uid = req.uid > 0 ? req.uid : 0;
	const canViewUsers = await privileges.global.can('groups:view:users', uid);
	if (!canViewUsers) {
		return res.status(403).json({
			error: '[[error:no-privilege]]',
		});
	}

	// The username portion of the acct: URI
	const userslug = String(resource).slice('acct:'.length, -(`@${hostname}`).length);
	const targetUid = await user.getUidByUserslug(userslug);
	if (!targetUid) {
		return res.status(404).json({
			error: '[[error:user-does-not-exist]]',
		});
	}

	const baseUrl = nconf.get('base_url');
	const relativePath = nconf.get('relative_path') || '';
	const uidUrl = `${baseUrl}${relativePath}/uid/${targetUid}`;
	const profileUrl = `${baseUrl}${relativePath}/user/${userslug}`;

	return res.status(200).json({
		subject: resource,
		aliases: [uidUrl, profileUrl],
		links: [
			{
				rel: 'http://webfinger.net/rel/profile-page',
				type: 'text/html',
				href: profileUrl,
			},
		],
	});
};
