diff --git a/test/well-known.js b/test/well-known.js
new file mode 100644
index 0000000..b3857e3
--- /dev/null
+++ b/test/well-known.js
@@ -0,0 +1,118 @@
+'use strict';
+
+const assert = require('assert');
+const nconf = require('nconf');
+const request = require('request');
+const requestAsync = require('request-promise-native');
+
+const db = require('./mocks/databasemock');
+const User = require('../src/user');
+const Groups = require('../src/groups');
+const privileges = require('../src/privileges');
+const helpers = require('./helpers');
+
+describe('well-known routes', () => {
+	let fooUid;
+	let slug;
+	const host = nconf.get('url_parsed').hostname;
+
+	before(async () => {
+		fooUid = await User.create({ username: 'webfingerfoo', password: 'barbar', gdpr_consent: true });
+		slug = await User.getSlug(fooUid);
+	});
+
+	it('should redirect /.well-known/change-password to /me/edit/password', async () => {
+		const res = await requestAsync.get(`${nconf.get('url')}/.well-known/change-password`, {
+			followRedirect: false,
+			resolveWithFullResponse: true,
+		});
+		assert.strictEqual(res.statusCode, 307);
+		assert.ok(res.headers.location.endsWith('/me/edit/password'), `location was ${res.headers.location}`);
+	});
+
+	it('should 400 when resource param is missing', async () => {
+		const res = await requestAsync.get(`${nconf.get('url')}/.well-known/webfinger`, {
+			json: true,
+			resolveWithFullResponse: true,
+		});
+		assert.strictEqual(res.statusCode, 400);
+	});
+
+	it('should 400 when resource does not start with acct:', async () => {
+		const res = await requestAsync.get(`${nconf.get('url')}/.well-known/webfinger`, {
+			qs: { resource: `webfingerfoo@${host}` },
+			json: true,
+			resolveWithFullResponse: true,
+		});
+		assert.strictEqual(res.statusCode, 400);
+	});
+
+	it('should 400 when resource hostname does not match', async () => {
+		const res = await requestAsync.get(`${nconf.get('url')}/.well-known/webfinger`, {
+			qs: { resource: `acct:webfingerfoo@other.example.com` },
+			json: true,
+			resolveWithFullResponse: true,
+		});
+		assert.strictEqual(res.statusCode, 400);
+	});
+
+	it('should 404 when user cannot be resolved', async () => {
+		const res = await requestAsync.get(`${nconf.get('url')}/.well-known/webfinger`, {
+			qs: { resource: `acct:does-not-exist-${Date.now()}@${host}` },
+			json: true,
+			resolveWithFullResponse: true,
+		});
+		assert.strictEqual(res.statusCode, 404);
+	});
+
+	it('should 200 with valid webfinger payload for a guest (guests have groups:view:users)', async () => {
+		const res = await requestAsync.get(`${nconf.get('url')}/.well-known/webfinger`, {
+			qs: { resource: `acct:${slug}@${host}` },
+			json: true,
+			resolveWithFullResponse: true,
+		});
+		assert.strictEqual(res.statusCode, 200);
+		const data = res.body;
+		assert.strictEqual(data.subject, `acct:${slug}@${host}`);
+		assert.ok(Array.isArray(data.aliases) && data.aliases.length === 2, `aliases: ${JSON.stringify(data.aliases)}`);
+		assert.ok(data.aliases[0].includes(`${nconf.get('relative_path')}/user/${slug}`), 'slug alias');
+		assert.ok(data.aliases.some(a => a.includes(`uid:${fooUid}`)), 'uid alias');
+		assert.ok(Array.isArray(data.links) && data.links.length >= 1);
+		assert.ok(data.links.some(link => link.href && link.href.includes(`/user/${slug}`)), 'links should reference /user/<slug>');
+	});
+
+	it('should 403 when guests lack groups:view:users', async () => {
+		await privileges.global.rescind(['groups:view:users'], 'guests');
+		try {
+			const res = await requestAsync.get(`${nconf.get('url')}/.well-known/webfinger`, {
+				qs: { resource: `acct:${slug}@${host}` },
+				json: true,
+				resolveWithFullResponse: true,
+			});
+			assert.strictEqual(res.statusCode, 403);
+		} finally {
+			await privileges.global.give(['groups:view:users'], 'guests');
+		}
+	});
+
+	it('should 200 for a logged in user with groups:view:users', async () => {
+		const { jar } = await helpers.loginUser('webfingerfoo', 'barbar');
+		const res = await requestAsync.get(`${nconf.get('url')}/.well-known/webfinger`, {
+			qs: { resource: `acct:${slug}@${host}` },
+			json: true,
+			jar,
+			resolveWithFullResponse: true,
+		});
+		assert.strictEqual(res.statusCode, 200);
+		assert.strictEqual(res.body.subject, `acct:${slug}@${host}`);
+	});
+
+	it('should 404 via uid alias too (unknown user)', async () => {
+		const res = await requestAsync.get(`${nconf.get('url')}/.well-known/webfinger`, {
+			qs: { resource: `acct:nope-${Date.now()}@${host}` },
+			json: true,
+			resolveWithFullResponse: true,
+		});
+		assert.strictEqual(res.statusCode, 404);
+	});
+});
